// Night Skull — 게임 + 계정 저장 + 실시간 멀티 서버, 파일 하나로 끝 (Node.js 18+, 외부 패키지 없음)
// 실행:  node server.js      → http://localhost:3000
// 설정:  PORT=8080 node server.js   (서버 20개 A1~A10, B1~B10 / 서버당 최대 30명)
'use strict';
const http = require('http');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const PORT = +process.env.PORT || 3000;
const CAP = 30;   // 서버당 최대 30명
const SERVERS = ['A', 'B'].flatMap(L => Array.from({ length: 10 }, (_, i) => L + (i + 1)));   // A1~A10, B1~B10 (총 20개)
const ROOT = __dirname;
const GAME_GZ_B64 = '';
const DATA = path.join(ROOT, 'data', 'accounts');
try { fs.mkdirSync(DATA, { recursive: true }); } catch (e) {}

// ---------------- 계정 저장소 ----------------
// 기본: data/accounts/<key>.json 파일
// Render 무료처럼 디스크가 날아가는 곳: UPSTASH_REDIS_REST_URL + UPSTASH_REDIS_REST_TOKEN 을 넣으면 Upstash(무료 Redis)에 영구 저장
const KEY_RE = /^u[0-9a-f]{2,128}$/;
const sha = s => crypto.createHash('sha256').update(String(s)).digest('hex');
const UP_URL = (process.env.UPSTASH_REDIS_REST_URL || '').replace(/\/$/, ''), UP_TOK = process.env.UPSTASH_REDIS_REST_TOKEN || '';
const useRedis = !!(UP_URL && UP_TOK);
const cache = new Map();
async function redis(cmd) {
  const r = await fetch(UP_URL, { method: 'POST', headers: { authorization: 'Bearer ' + UP_TOK, 'content-type': 'application/json' }, body: JSON.stringify(cmd) });
  if (!r.ok) throw new Error('redis ' + r.status); const j = await r.json(); if (j.error) throw new Error(j.error); return j.result;
}
const file = k => path.join(DATA, k + '.json');
async function readAcc(k) {
  if (cache.has(k)) return cache.get(k);
  let a = null;
  if (useRedis) { const v = await redis(['GET', 'sod:acc:' + k]); a = v ? JSON.parse(v) : null; }
  else { try { a = JSON.parse(fs.readFileSync(file(k), 'utf8')); } catch (e) { a = null; } }
  if (a) cache.set(k, a); return a;
}
async function writeAcc(k, obj) {
  if (useRedis) await redis(['SET', 'sod:acc:' + k, JSON.stringify(obj)]);
  else { const f = file(k), tmp = f + '.' + process.pid + '.tmp'; fs.writeFileSync(tmp, JSON.stringify(obj)); fs.renameSync(tmp, f); }
  cache.set(k, obj);
}
function safeEq(a, b) { a = Buffer.from(String(a)); b = Buffer.from(String(b)); return a.length === b.length && crypto.timingSafeEqual(a, b); }
const pub = a => { const { h2, ...rest } = a; return rest; }; // 비밀번호 정보는 절대 내보내지 않음

// 로그인 시도 제한 (IP+계정당 1분 10회)
const tries = new Map();
function limited(ip, k) { const id = ip + '|' + k, now = Date.now(); let t = tries.get(id); if (!t || now - t.s > 60000) t = { s: now, n: 0 }; t.n++; tries.set(id, t); return t.n > 10; }

function body(req) {
  return new Promise((res, rej) => { let n = 0; const chunks = [];
    req.on('data', c => { n += c.length; if (n > 2e6) { rej(413); req.destroy(); } else chunks.push(c); });
    req.on('end', () => { try { res(JSON.parse(Buffer.concat(chunks).toString('utf8') || '{}')); } catch (e) { rej(400); } });
    req.on('error', () => rej(400)); });
}
function send(res, code, obj) { const b = JSON.stringify(obj); res.writeHead(code, { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' }); res.end(b); }

async function api(req, res, url) {
  const ip = req.socket.remoteAddress || '';
  if (url.pathname === '/api/servers') { const out = []; for (const [id, r] of rooms) if (r.size) out.push({ id, c: r.size, max: CAP }); out.sort((a, b) => a.id[0] === b.id[0] ? (+a.id.slice(1)) - (+b.id.slice(1)) : a.id < b.id ? -1 : 1); return send(res, 200, { servers: out }); }
  if (url.pathname === '/api/ping') return send(res, 200, { game: 'sod', ok: true, store: useRedis ? 'redis' : 'file' });
  let m = url.pathname.match(/^\/api\/acc\/([^/]+)$/);
  if (m) {
    const k = m[1]; if (!KEY_RE.test(k)) return send(res, 400, { error: 'key' });
    const a = await readAcc(k);
    if (req.method === 'GET') return send(res, 200, a ? { exists: true, name: a.name, salt: a.salt } : { exists: false });
    if (req.method === 'PUT') {
      const b = await body(req); if (!a) return send(res, 404, { error: 'none' });
      if (!b || !safeEq(sha(b.hash), a.h2)) return send(res, 401, { error: 'auth' });
      await writeAcc(k, { ...a, save: b.save === undefined ? a.save : b.save, updatedAt: Date.now() });
      return send(res, 200, { ok: true });
    }
  }
  if (url.pathname === '/api/signup' && req.method === 'POST') {
    const b = await body(req); const k = b && b.key, d = b && b.doc;
    if (!KEY_RE.test(k || '') || !d || typeof d.hash !== 'string' || typeof d.salt !== 'string') return send(res, 400, { error: 'bad' });
    if (await readAcc(k)) return send(res, 409, { error: 'exists' });
    await writeAcc(k, { name: String(d.name || '').slice(0, 16), salt: d.salt.slice(0, 64), h2: sha(d.hash), created: Date.now(), save: null, updatedAt: Date.now() });
    return send(res, 200, { ok: true });
  }
  if (url.pathname === '/api/login' && req.method === 'POST') {
    const b = await body(req); const k = b && b.key;
    if (!KEY_RE.test(k || '')) return send(res, 400, { error: 'bad' });
    if (limited(ip, k)) return send(res, 429, { error: 'slow' });
    const a = await readAcc(k); if (!a || !safeEq(sha(b.hash), a.h2)) return send(res, 401, { error: 'auth' });
    return send(res, 200, pub(a));
  }
  send(res, 404, { error: 'nf' });
}

// ---------------- 게임 페이지 (이 파일 안에 압축되어 들어있음) ----------------
// 홈 화면 설치(PWA): manifest + 아이콘 + 서비스워커를 이 파일이 직접 제공
const HEAD_ADD = [
  '<link rel="manifest" href="/manifest.webmanifest">',
  '<link rel="apple-touch-icon" href="/apple-touch-icon.png">',
  '<link rel="icon" type="image/png" href="/icon-192.png">',
  '<meta name="theme-color" content="#0b1230">',
  '<meta name="mobile-web-app-capable" content="yes">',
  '<meta name="apple-mobile-web-app-capable" content="yes">',
  '<meta name="apple-mobile-web-app-status-bar-style" content="black-translucent">',
  '<meta name="apple-mobile-web-app-title" content="Night Skull">',
  "<script>if('serviceWorker' in navigator)addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}));</script>"
].join('');
const PAGE = Buffer.from(require('zlib').gunzipSync(Buffer.from(GAME_GZ_B64, 'base64')).toString('utf8')
  .replace('</head>', HEAD_ADD + '</head>')
  .replace(/<meta name="viewport" content="([^"]*)">/, (m, c) => '<meta name="viewport" content="' + (c.includes('viewport-fit') ? c : c + ',viewport-fit=cover') + '">'), 'utf8');
const ICON192 = Buffer.from('', 'base64'), ICON512 = Buffer.from('', 'base64');
const MANIFEST = JSON.stringify({
  name: 'Night Skull', short_name: 'Night Skull', id: '/', start_url: '/', scope: '/', display: 'fullscreen',
  orientation: 'portrait', background_color: '#0b1230', theme_color: '#0b1230',
  icons: [{ src: '/icon-192.png', sizes: '192x192', type: 'image/png', purpose: 'any' }, { src: '/icon-512.png', sizes: '512x512', type: 'image/png', purpose: 'any' },
          { src: '/icon-512.png', sizes: '512x512', type: 'image/png', purpose: 'maskable' }]
});
const SW = `const C='ns-v1';
self.addEventListener('install',e=>{self.skipWaiting();e.waitUntil(caches.open(C).then(c=>c.addAll(['/','/icon-192.png'])).catch(()=>{}));});
self.addEventListener('activate',e=>e.waitUntil(self.clients.claim()));
self.addEventListener('fetch',e=>{const u=new URL(e.request.url);if(e.request.method!=='GET'||u.pathname.startsWith('/api/')||u.pathname==='/ws')return;
  e.respondWith(fetch(e.request).then(r=>{if(r.ok&&u.origin===location.origin){const cp=r.clone();caches.open(C).then(c=>c.put(e.request,cp));}return r;}).catch(()=>caches.match(e.request).then(r=>r||caches.match('/'))));});`;
function serveStatic(req, res, url) {
  const p = url.pathname;
  if (p === '/' || p === '/index.html') { res.writeHead(200, { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-cache' }); return res.end(PAGE); }
  if (p === '/manifest.webmanifest') { res.writeHead(200, { 'content-type': 'application/manifest+json' }); return res.end(MANIFEST); }
  if (p === '/sw.js') { res.writeHead(200, { 'content-type': 'text/javascript', 'cache-control': 'no-cache', 'service-worker-allowed': '/' }); return res.end(SW); }
  if (p === '/icon-192.png' || p === '/apple-touch-icon.png' || p === '/apple-touch-icon-precomposed.png' || p === '/favicon.ico') { res.writeHead(200, { 'content-type': 'image/png', 'cache-control': 'max-age=86400' }); return res.end(ICON192); }
  if (p === '/icon-512.png') { res.writeHead(200, { 'content-type': 'image/png', 'cache-control': 'max-age=86400' }); return res.end(ICON512); }
  res.writeHead(404); res.end('not found');
}

const server = http.createServer((req, res) => {
  const url = new URL(req.url, 'http://x');
  if (url.pathname.startsWith('/api/')) api(req, res, url).catch(e => send(res, typeof e === 'number' ? e : 500, { error: 'err' }));
  else serveStatic(req, res, url);
});

// ---------------- 실시간 (WebSocket, RFC 6455 직접 구현) ----------------
const rooms = new Map(); // 'A1','A2','B1'… -> Set(client)  (글자=맵, 숫자=서버)
let nextId = 1;
function frame(str) {
  const p = Buffer.from(str, 'utf8'), n = p.length; let h;
  if (n < 126) { h = Buffer.from([0x81, n]); }
  else if (n < 65536) { h = Buffer.alloc(4); h[0] = 0x81; h[1] = 126; h.writeUInt16BE(n, 2); }
  else { h = Buffer.alloc(10); h[0] = 0x81; h[1] = 127; h.writeBigUInt64BE(BigInt(n), 2); }
  return Buffer.concat([h, p]);
}
function wsSend(cl, obj) { if (cl.alive) try { cl.sock.write(frame(JSON.stringify(obj))); } catch (e) {} }
function broadcast(cl, obj) { const r = cl.room && rooms.get(cl.room); if (!r) return; for (const o of r) if (o !== cl) wsSend(o, obj); }
function leave(cl) {
  if (!cl.alive) return; cl.alive = false;
  const r = cl.room && rooms.get(cl.room);
  if (r) { r.delete(cl); broadcast(cl, { t: 'bye', id: cl.id }); if (!r.size) rooms.delete(cl.room); }
  try { cl.sock.destroy(); } catch (e) {}
}
function onMsg(cl, txt) {
  if (txt.length > 8192) return;
  const now = Date.now(); if (now - cl.win > 1000) { cl.win = now; cl.cnt = 0; } if (++cl.cnt > 60) return; // 초당 60개 제한
  let m; try { m = JSON.parse(txt); } catch (e) { return; }
  if (m.t === 'join') {
    const want = String(m.id || 'A1').toUpperCase();
    const size = id => { const r = rooms.get(id); return r ? r.size - (r.has(cl) ? 1 : 0) : 0; };
    let id = SERVERS.includes(want) ? want : 'A1';
    if (size(id) >= CAP) {
      if (m.exact) { wsSend(cl, { t: 'err', code: 'full' }); return; }
      const free = SERVERS.find(x => size(x) < CAP);   // 꽉 차면 다음 서버로 자동 배정
      if (!free) { wsSend(cl, { t: 'err', code: 'full' }); return; }
      id = free;
    }
    if (cl.room === id) { wsSend(cl, { t: 'hello', id: cl.id, room: id }); return; }
    if (cl.room) { const o = rooms.get(cl.room); if (o) { o.delete(cl); broadcast(cl, { t: 'bye', id: cl.id, quiet: true }); if (!o.size) rooms.delete(cl.room); } }
    let r = rooms.get(id); if (!r) rooms.set(id, r = new Set());
    cl.room = id; cl.last = null; r.add(cl); wsSend(cl, { t: 'hello', id: cl.id, room: id });
    for (const o of r) if (o !== cl && o.last) wsSend(cl, { t: 'p', id: o.id, d: o.last });
    return;
  }
  if (m.t === 'p' && cl.room && m.d && typeof m.d === 'object') { cl.last = m.d; broadcast(cl, { t: 'p', id: cl.id, d: m.d }); }
}
server.on('upgrade', (req, sock) => {
  if (new URL(req.url, 'http://x').pathname !== '/ws' || (req.headers.upgrade || '').toLowerCase() !== 'websocket') { sock.destroy(); return; }
  const key = req.headers['sec-websocket-key']; if (!key) { sock.destroy(); return; }
  const acc = crypto.createHash('sha1').update(key + '258EAFA5-E914-47DA-95CA-C5AB0DC85B11').digest('base64');
  sock.write('HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: ' + acc + '\r\n\r\n');
  sock.setNoDelay(true);
  const cl = { id: 'c' + (nextId++), sock, alive: true, room: null, last: null, buf: Buffer.alloc(0), frag: [], win: 0, cnt: 0, pong: Date.now() };
  sock.on('data', d => {
    cl.buf = Buffer.concat([cl.buf, d]); if (cl.buf.length > 1e6) return leave(cl);
    while (cl.buf.length >= 2) {
      const b0 = cl.buf[0], b1 = cl.buf[1], op = b0 & 15, fin = b0 & 128, masked = b1 & 128; let len = b1 & 127, off = 2;
      if (len === 126) { if (cl.buf.length < 4) return; len = cl.buf.readUInt16BE(2); off = 4; }
      else if (len === 127) { if (cl.buf.length < 10) return; len = Number(cl.buf.readBigUInt64BE(2)); off = 10; }
      if (len > 65536) return leave(cl);
      const need = off + (masked ? 4 : 0) + len; if (cl.buf.length < need) return;
      let pay = cl.buf.subarray(off + (masked ? 4 : 0), need);
      if (masked) { const mk = cl.buf.subarray(off, off + 4); pay = Buffer.from(pay); for (let i = 0; i < pay.length; i++) pay[i] ^= mk[i & 3]; }
      cl.buf = cl.buf.subarray(need);
      if (op === 8) return leave(cl);
      if (op === 9) { try { sock.write(Buffer.concat([Buffer.from([0x8a, pay.length]), pay])); } catch (e) {} continue; }
      if (op === 10) { cl.pong = Date.now(); continue; }
      if (op === 1 || op === 0) { cl.frag.push(pay); if (fin) { const t = Buffer.concat(cl.frag).toString('utf8'); cl.frag = []; cl.pong = Date.now(); onMsg(cl, t); } }
    }
  });
  sock.on('close', () => leave(cl)); sock.on('error', () => leave(cl));
  cl.ping = setInterval(() => { if (!cl.alive) return clearInterval(cl.ping); if (Date.now() - cl.pong > 30000) { clearInterval(cl.ping); return leave(cl); } try { sock.write(Buffer.from([0x89, 0])); } catch (e) {} }, 10000);
});

server.listen(PORT, () => {
  const nets = require('os').networkInterfaces(); const ips = [];
  for (const k in nets) for (const n of nets[k]) if (n.family === 'IPv4' && !n.internal) ips.push(n.address);
  console.log('Night Skull 서버 실행 중');
  console.log('  이 컴퓨터:   http://localhost:' + PORT);
  for (const ip of ips) console.log('  같은 와이파이: http://' + ip + ':' + PORT);
  console.log('  서버:        ' + SERVERS.length + '개 (A1~A10, B1~B10, 서버당 최대 ' + CAP + '명)');
  console.log('  저장소:      ' + (useRedis ? 'Upstash Redis (영구)' : '파일 data/accounts'));
});
